use super::*;
fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);*fuel=fuel.checked_sub(work).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
#[test]fn actual_ordered_shared_birth_null_and_release_keep_input_and_exact_work(){let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut input=Some(row["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();for grant in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_capacity_bytes:SharedOwner::<String>::allocation_bytes()-1,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let turn=SharedOwner::admit(input.take().unwrap(),grant);assert_eq!(turn.work,row["deniedWork"].as_u64().unwrap());let(_,original)=turn.result.err().unwrap();assert_eq!(original.as_ptr(),pointer);input=Some(original)}
 let((turn,attempts),heap)=crate::allocation_testing::observe_retirement_allocations(||crate::allocation_testing::refuse_one_allocation_on_this_thread(||SharedOwner::admit(input.take().unwrap(),RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,row["nullWork"].as_u64().unwrap());fuel-=turn.work;let(_,original)=turn.result.err().unwrap();assert_eq!(original.as_ptr(),pointer);input=Some(original);let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||SharedOwner::admit(input.take().unwrap(),RetainedCloneGrant{maximum_items:1,..bank}));let(mut owner,p)=turn.result.map_err(|(error,_)|error).unwrap();assert_eq!(turn.work,row["admitWork"].as_u64().unwrap());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));post(&mut bank,&mut fuel,p,turn.work);assert_eq!(owner.deref().as_ptr(),pointer);assert_eq!(serde_json::to_value(owner.deref()).unwrap(),row["value"]);
 let denied=owner.release_step(RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,row["deniedWork"].as_u64().unwrap());assert_eq!(denied.result.unwrap().progress,Default::default());assert_eq!(owner.deref().as_ptr(),pointer);let(turn,heap)=crate::allocation_testing::observe_retirement_allocations(||owner.release_step(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,row["releaseWork"].as_u64().unwrap());let released=turn.result.unwrap();assert_eq!(heap,(released.progress.retained_capacity_bytes,released.progress.released_bytes));post(&mut bank,&mut fuel,released.progress,turn.work);assert!(owner.terminal_is_empty());assert_eq!(owner.release_step(Default::default()).work,row["cachedWork"].as_u64().unwrap());let mut close=crate::retirement::controlled::ControlledRetirement::new(released.value.unwrap()).map_err(|(error,_)|error).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if close.terminal_is_empty(){break}let step=close.step(RetainedCloneGrant{maximum_items:1,..bank}).unwrap();post(&mut bank,&mut fuel,step.progress(),close.last_turn_work());}assert!(close.terminal_is_empty());}
